// REQ-TOOL8 · DEMO de `game.herramientas`: una herramienta que NO existe en el motor, definida entera aquí.
// El motor no sabe qué es una espada: solo lleva el dibujo en la mano, le anima el gesto y avisa del clic.
//
//   ▸ Correr este snippet ya te la pone en la mano.
//   ▸ Clic IZQUIERDO  = tajo   → dice qué has golpeado y cuenta los tajos (`game.espada.golpes`).
//   ▸ Clic DERECHO    = estocada → un impulso hacia donde miras. No toca el mundo.
//   ▸ Rosca del ratón = la espada es el peldaño de ARRIBA del todo (encima del cuentagotas).
//   ▸ Para quitarla:   game.herramientas.quita('espada')
//
// Retoques en caliente desde F12 (redefine y ya, sin recargar):
//   game.herramientas.define('espada', { ...game.herramientas.info('espada'), escala: 1.6 })
//   game.herramientas.info()          → cómo quedó la ficha
//   game.herramientas.golpea()        → lanza el gesto sin hacer clic (para tunear la animación)
//   game.espada.impulso = 14          → estocadas más largas (y `game.espada.despegue`, cuánto se levanta)

game.herramientas.define('espada', {
  // ── QUÉ SE LLEVA EN LA MANO ────────────────────────────────────────────────────────────────────
  // Cualquier clave del catálogo: un habitante (`hab:...`) o un asset (`asset:assets/x.vox.json`).
  dibujo: 'espada',
  nombre: '🗡️ Espada',
  mira: '·',                       // el punto de mira mientras esté puesta
  ayuda: 'Espada · clic izq: tajo · clic dcho: estocada',

  // ── POSTURA EN LA MANO ─────────────────────────────────────────────────────────────────────────
  // Lo que no se ponga aquí cae en los mandos globales de siempre (`game.showTool.pos/rot/scale`).
  pos: [0.85, -0.55, 0],
  rot: [-6, -80, -18],
  escala: 0.75,
  alcance: 4,                      // hasta dónde llega el tajo (bloques); sin esto, el alcance normal

  // ── EL GESTO DEL CLIC ──────────────────────────────────────────────────────────────────────────
  // Misma máquina de 3 fases del pico (impulso → golpe → vuelta); lo que no se toque hereda del pico.
  // Una espada es más rápida y más plana que un hachazo: casi no baja, pero llega más lejos y gira más.
  gesto: { dur: 0.20, windupP: 0.12, strikeP: 0.42, windupRot: -55, chopRot: 60, lift: 0.16, drop: 0.05, reach: 0.55 },
  gestoBotones: [0, 2],            // se anima con los DOS botones (por defecto solo el izquierdo)

  // ── MOVIMIENTO PROPIO (opcional) ───────────────────────────────────────────────────────────────
  // Se llama en cada frame con lo ya calculado y devuelve desplazamientos que se SUMAN: eje de cámara
  // (x derecha, y arriba, z hacia ti) y grados. Aquí, un vaivén de reposo que se apaga durante el tajo.
  anima(e){
    const quieta = (e.golpe < 0) ? 1 : 0;          // e.golpe = 0..1 mientras dura el gesto, -1 si está parada
    return {
      pos: [0, Math.sin(e.t * 1.4) * 0.012 * quieta, 0],
      rot: [0, 0, Math.sin(e.t * 0.9) * 2.5 * quieta]
    };
  },

  // ── LO QUE PASA AL HACER CLIC ──────────────────────────────────────────────────────────────────
  // `c` viene masticado: c.celda (bloque apuntado), c.clave (su material), c.delante (la celda de al
  // lado, donde se pondría algo), c.punto, c.dist, c.normal, c.pos/yaw/pitch, c.ranura, c.bloque.
  izquierdo(c){
    game.espada.golpes++;
    // ── 1º: ¿un agente ARTICULADO? ────────────────────────────────────────────────────────────
    // `c` habla de celdas y materiales, y una pieza de agente no es ni una cosa ni la otra: es una
    // estructura efímera que el rig mueve por matriz, sin voxel en el mundo. Por eso hay que
    // preguntar a la librería, que además dice DÓNDE ha caído: `local` es el voxel dentro del
    // dibujo de la pieza (índices del editor) y `alto` esa misma altura en 0..1, ya masticada.
    // Ahí es donde iría el efecto de la herramienta, sea un tajo o una margarita.
    const h = (window.game && game.esqueletos && game.esqueletos.enLaMira) ? game.esqueletos.enLaMira() : null;
    if(h){
      // 🩸 Y aquí es donde sirve de algo saber el punto exacto: la sangre sale DE la herida.
      game.sangre.salpica(h.punto);
      const zona = h.alto > 0.75 ? 'en lo alto' : (h.alto < 0.3 ? 'abajo' : 'a media altura');
      toast('🗡️ Tajo #' + game.espada.golpes + ' a ' + h.texto + ' · ' + zona
            + ' (voxel ' + h.local.join(',') + ' de ' + h.dim.join('×') + ')');
      return;
    }
    // ── 2º: los NPC-cubo. `mc.agents` es otro mundo (1×1×1, sin piezas). Solo se MIRAN.
    const cerca = [];
    for(const a of mc.agents.values()){
      const d = Math.hypot(a.x - c.pos[0], a.y - c.pos[1], a.z - c.pos[2]);
      if(d <= 3.5) cerca.push((a.name || a.id) + ' a ' + d.toFixed(1));
    }
    if(cerca.length) toast('🗡️ ¡Tajo! alcanzas a ' + cerca.join(', '));
    else if(c.clave)  toast('🗡️ Tajo #' + game.espada.golpes + ' sobre ' + c.clave + ' en ' + c.celda.join(','));
    else              toast('🗡️ Tajo #' + game.espada.golpes + ' al aire');
  },

  derecho(c){
    // Estocada: un empujón hacia donde miras. Ni rompe ni pone nada — el mundo se queda como estaba.
    // ⚠️ Con los pies en el suelo, `mc.vel[0]/[2]` se REESCRIBEN en cada frame desde las teclas de
    // marcha (app.js:11134), así que un empujón horizontal a secas se borra antes de verse. En el AIRE,
    // en cambio, la inercia se conserva ⇒ la estocada despega un poco y ya vuela hacia donde miras.
    const cp = Math.cos(mc.pitch), f = game.espada.impulso;
    mc.vel[0] = -Math.sin(mc.yaw) * cp * f;
    mc.vel[2] = -Math.cos(mc.yaw) * cp * f;
    mc.vel[1] = Math.max(mc.vel[1], game.espada.despegue * Math.sqrt(mc.scale));
    mc.onGround = false;
    game.espada.estocadas++;
    toast('⚔️ ¡Estocada! (' + game.espada.estocadas + ')' + (c.clave ? ' contra ' + c.clave : ''));
  }
});

// Los contadores y el mando de la estocada viven en `game`, no en el motor: son de esta herramienta.
game.espada = { golpes: 0, estocadas: 0, impulso: 10, despegue: 3.2 };

// ── 🩸 Sangre: 12 líneas de configuración, el motor está en otro sitio ───────────────────────────
// El sitio del golpe lo da BUG-AG19 (`game.esqueletos.enLaMira().punto`); esto es lo que se dibuja
// ahí. La física, el rebote, el desvanecido y las sondas del mundo NO viven aquí: esto era el 63%
// de este fichero y se fue a dos librerías, que es lo que pidió el dueño (REQ-SNP-LIB1/2):
//
//   · `particulas-voxel` — el motor: caer, chocar, posarse, apagarse. Un rAF para todos los efectos.
//   · `sondas-mundo`     — «¿hay materia de verdad aquí?», por FORMA y no por celda (la foto #56).
//
// Para tocar el EFECTO se toca aquí. Para tocar la FÍSICA se toca la librería, y se arregla para
// todos a la vez. `game.efectos-demo` enseña qué más sale de este mismo motor.
const P = await game.snippet('particulas-voxel');
game.sangre = P.crea({
  grupo: 'sangre',       // su sitio en game.voxelesUI: limpiarla no toca lo que haya plantado nadie
  chorro: 22,            // gotas por tajo
  dura: 30,              // segundos tiradas en el suelo (lo que pidió el dueño)
  desvanece: 4,          // los últimos N de esos segundos, oscureciéndose
  grav: 24,              // más que la del jugador: son gotas, no sacos
  fuerza: 5.5,
  rebote: 0.22,
  vuelo: 8,
  tope: 500,
  hacia: 'mirada',       // salen al revés de por donde ha entrado el filo
  colores: [[0.78,0.08,0.08],[0.66,0.05,0.05],[0.88,0.15,0.12],[0.55,0.03,0.03],[0.83,0.23,0.11]]
});

// …y a la mano.
game.playerTool = 'espada';
toast('🗡️ Espada lista · clic izq: tajo · clic dcho: estocada · rosca abajo para cambiar');
